def gen(rng):
    LIM = 10 ** 9
    def tdiv(a, b):
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q
    def build(m, vmax, push_p):
        toks, st, pushed = [], [], 0
        while pushed < m or len(st) > 1:
            if len(st) >= 2 and (pushed == m or rng.random() > push_p):
                b = st.pop()
                a = st.pop()
                ops = ['+', '-', '*']
                if b != 0:
                    ops.append('/')
                rng.shuffle(ops)
                for op in ops:
                    if op == '+':
                        r = a + b
                    elif op == '-':
                        r = a - b
                    elif op == '*':
                        r = a * b
                    else:
                        r = tdiv(a, b)
                    if abs(r) <= LIM:
                        break
                toks.append(op)
                st.append(r)
            else:
                v = rng.randint(-vmax, vmax)
                toks.append(str(v))
                st.append(v)
                pushed += 1
        return str(len(toks)) + '\n' + ' '.join(toks)
    tests = ['1\n0', '1\n-5', '1\n1000000000', '3\n6 -4 /', '3\n-7 2 /', '3\n7 -2 /', '3\n0 5 -', '5\n-1000000000 1000000000 + 3 *']
    for m in (2, 3, 3, 4, 5, 6, 8, 10):
        for vm in (5, 30):
            tests.append(build(m, vm, 0.55))
    tests.append(build(40, 10 ** 9, 0.5))
    tests.append(build(2000, 9, 0.5))
    tests.append(build(20000, 10 ** 9, 0.5))
    tests.append(build(50000, 12, 0.97))
    tests.append(build(50000, 1000, 0.03))
    tests.append(build(50000, 10 ** 9, 0.5))
    return tests

